//! Checks that `create_proof` is deterministic for a given RNG, and that the proof bytes
//! for several circuits match the ones produced by the original serial prover.
//!
//! The prover may schedule independent per-circuit work (such as witness synthesis) in
//! parallel, but it must draw randomness and write to the transcript in a fixed order.
//! The expected digests below were generated by the unmodified halo2_proofs 0.3.2 prover,
//! which processes circuits strictly one after another.

use group::ff::Field;
use halo2_proofs::{
    circuit::{Layouter, SimpleFloorPlanner, Value},
    pasta::{EqAffine, Fp},
    plonk::{
        create_proof, keygen_pk, keygen_vk, verify_proof, Advice, Circuit, Column,
        ConstraintSystem, Error, Instance, ProvingKey, Selector, SingleVerifier, TableColumn,
    },
    poly::{commitment::Params, Rotation},
    transcript::{Blake2bRead, Blake2bWrite, Challenge255},
};
use rand_core::{impls, RngCore};

const K: u32 = 6;
const ROWS: usize = 20;
const RANGE: u64 = 16;
const SQUARES: u64 = 8;

/// A tiny deterministic RNG (SplitMix64), so that the test needs no extra dependencies.
struct TestRng(u64);

impl RngCore for TestRng {
    fn next_u32(&mut self) -> u32 {
        self.next_u64() as u32
    }

    fn next_u64(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9e37_79b9_7f4a_7c15);
        let mut z = self.0;
        z = (z ^ (z >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        z ^ (z >> 31)
    }

    fn fill_bytes(&mut self, dest: &mut [u8]) {
        impls::fill_bytes_via_next(self, dest)
    }

    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), rand_core::Error> {
        self.fill_bytes(dest);
        Ok(())
    }
}

#[derive(Clone, Debug)]
struct TestConfig {
    advice: [Column<Advice>; 6],
    instance: Column<Instance>,
    s_mul: Selector,
    range_table: TableColumn,
    square_table: (TableColumn, TableColumn),
}

/// A circuit with several advice columns, two lookup arguments, a permutation argument
/// that spans more than one column set, and an instance column, so that every
/// per-circuit stage of the prover is exercised.
#[derive(Clone, Default)]
struct TestCircuit {
    seed: Value<u64>,
}

impl Circuit<Fp> for TestCircuit {
    type Config = TestConfig;
    type FloorPlanner = SimpleFloorPlanner;

    fn without_witnesses(&self) -> Self {
        Self::default()
    }

    fn configure(meta: &mut ConstraintSystem<Fp>) -> TestConfig {
        let advice = [(); 6].map(|_| meta.advice_column());
        let instance = meta.instance_column();
        let constant = meta.fixed_column();
        meta.enable_constant(constant);
        for column in advice {
            meta.enable_equality(column);
        }
        meta.enable_equality(instance);

        let s_mul = meta.selector();
        let range_table = meta.lookup_table_column();
        let square_table = (meta.lookup_table_column(), meta.lookup_table_column());

        // a0 * a1 = a3
        meta.create_gate("mul", |meta| {
            let s = meta.query_selector(s_mul);
            let a0 = meta.query_advice(advice[0], Rotation::cur());
            let a1 = meta.query_advice(advice[1], Rotation::cur());
            let a3 = meta.query_advice(advice[3], Rotation::cur());
            vec![s * (a0 * a1 - a3)]
        });

        // a0 is in [0, RANGE)
        meta.lookup(|meta| {
            let a0 = meta.query_advice(advice[0], Rotation::cur());
            vec![(a0, range_table)]
        });

        // a2 = a1^2 with a1 in [0, SQUARES)
        meta.lookup(|meta| {
            let a1 = meta.query_advice(advice[1], Rotation::cur());
            let a2 = meta.query_advice(advice[2], Rotation::cur());
            vec![(a1, square_table.0), (a2, square_table.1)]
        });

        TestConfig {
            advice,
            instance,
            s_mul,
            range_table,
            square_table,
        }
    }

    fn synthesize(&self, config: TestConfig, mut layouter: impl Layouter<Fp>) -> Result<(), Error> {
        layouter.assign_table(
            || "range table",
            |mut table| {
                for i in 0..RANGE {
                    table.assign_cell(
                        || "range",
                        config.range_table,
                        i as usize,
                        || Value::known(Fp::from(i)),
                    )?;
                }
                Ok(())
            },
        )?;
        layouter.assign_table(
            || "square table",
            |mut table| {
                for i in 0..SQUARES {
                    table.assign_cell(
                        || "x",
                        config.square_table.0,
                        i as usize,
                        || Value::known(Fp::from(i)),
                    )?;
                    table.assign_cell(
                        || "x^2",
                        config.square_table.1,
                        i as usize,
                        || Value::known(Fp::from(i * i)),
                    )?;
                }
                Ok(())
            },
        )?;

        layouter.assign_region(
            || "main",
            |mut region| {
                let [a0, a1, a2, a3, a4, a5] = config.advice;
                let mut prev_a3 = None;
                let mut prev_a5 =
                    region.assign_advice_from_instance(|| "seed", config.instance, 0, a5, 0)?;
                for row in 0..ROWS {
                    config.s_mul.enable(&mut region, row)?;
                    let x = self.seed.map(|seed| (seed + row as u64) % RANGE);
                    let y = Value::known(row as u64 % SQUARES);
                    region.assign_advice(|| "a0", a0, row, || x.map(Fp::from))?;
                    region.assign_advice(|| "a1", a1, row, || y.map(Fp::from))?;
                    let sq =
                        region.assign_advice(|| "a2", a2, row, || y.map(|y| Fp::from(y * y)))?;
                    if row == 0 {
                        region.constrain_constant(sq.cell(), Fp::ZERO)?;
                    }
                    let prod = region.assign_advice(
                        || "a3",
                        a3,
                        row,
                        || x.zip(y).map(|(x, y)| Fp::from(x * y)),
                    )?;
                    // a4 holds the previous row's product.
                    if let Some(prev) = prev_a3.replace(prod) {
                        prev.copy_advice(|| "a4", &mut region, a4, row)?;
                    }
                    if row > 0 {
                        prev_a5 = prev_a5.copy_advice(|| "a5", &mut region, a5, row)?;
                    }
                }
                Ok(())
            },
        )
    }
}

fn setup() -> (Params<EqAffine>, ProvingKey<EqAffine>) {
    let params: Params<EqAffine> = Params::new(K);
    let vk = keygen_vk(&params, &TestCircuit::default()).expect("keygen_vk should not fail");
    let pk = keygen_pk(&params, vk, &TestCircuit::default()).expect("keygen_pk should not fail");
    (params, pk)
}

fn prove(
    params: &Params<EqAffine>,
    pk: &ProvingKey<EqAffine>,
    circuits: &[TestCircuit],
    seeds: &[u64],
    rng_seed: u64,
) -> Result<Vec<u8>, Error> {
    let instances: Vec<[Fp; 1]> = seeds.iter().map(|seed| [Fp::from(*seed)]).collect();
    let instances: Vec<[&[Fp]; 1]> = instances.iter().map(|i| [&i[..]]).collect();
    let instances: Vec<&[&[Fp]]> = instances.iter().map(|i| &i[..]).collect();

    let mut transcript = Blake2bWrite::<_, _, Challenge255<_>>::init(vec![]);
    create_proof(
        params,
        pk,
        circuits,
        &instances,
        TestRng(rng_seed),
        &mut transcript,
    )?;
    let proof = transcript.finalize();

    let strategy = SingleVerifier::new(params);
    let mut transcript = Blake2bRead::<_, _, Challenge255<_>>::init(&proof[..]);
    assert!(verify_proof(params, pk.get_vk(), strategy, &instances, &mut transcript).is_ok());

    Ok(proof)
}

fn digest(proof: &[u8]) -> String {
    blake2b_simd::Params::new()
        .hash_length(32)
        .hash(proof)
        .to_hex()
        .to_string()
}

fn circuits(seeds: &[u64]) -> Vec<TestCircuit> {
    seeds
        .iter()
        .map(|seed| TestCircuit {
            seed: Value::known(*seed),
        })
        .collect()
}

#[test]
fn multi_circuit_proof_matches_serial_prover() {
    let (params, pk) = setup();

    let expected = [
        (
            vec![3],
            "2227119fb599d4e224f5df76f1e069454f06b86b3bee4d281d3165081b3a25c8",
        ),
        (
            vec![3, 7, 11, 13],
            "8997931e28232d766a384a205b9b06444c327b81a588a67af917e6f60b66f9d4",
        ),
        (
            vec![5, 5, 9, 2, 14, 0],
            "c3d1095ba106c9866a8db420e55ae26f49449394c2cc1f3f88612b02916dea8f",
        ),
    ];
    for (seeds, expected) in expected.iter() {
        let proof = prove(&params, &pk, &circuits(seeds), seeds, 0xda5).unwrap();
        // The same RNG seed must always produce the same proof.
        assert_eq!(
            proof,
            prove(&params, &pk, &circuits(seeds), seeds, 0xda5).unwrap()
        );
        assert_eq!(digest(&proof), *expected, "circuits with seeds {:?}", seeds);
    }
}

#[test]
fn synthesis_error_is_reported() {
    let (params, pk) = setup();

    let mut circuits = circuits(&[3, 7, 11]);
    circuits[1].seed = Value::unknown();
    assert!(matches!(
        prove(&params, &pk, &circuits, &[3, 7, 11], 1),
        Err(Error::Synthesis)
    ));
}
